import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    "m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
}

def col_to_idx(ref):
    m = re.match(r"([A-Z]+)(\d+)", ref)
    letters, row = m.group(1), int(m.group(2))
    col = 0
    for ch in letters:
        col = col * 26 + (ord(ch) - 64)
    return col, row

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    print("Files in archive:")
    for n in z.namelist():
        print("  ", n)
    print()

    # shared strings
    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in root.findall("m:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    # styles (to detect date/number formats if needed)
    styles = {}
    if "xl/styles.xml" in z.namelist():
        sroot = ET.fromstring(z.read("xl/styles.xml"))
        for i, fmt in enumerate(sroot.find("m:cellXfs", NS)):
            styles[i] = fmt.get("numFmtId")

    wbroot = ET.fromstring(z.read("xl/workbook.xml"))
    sheets = [(s.get("name"), s.get("{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"))
              for s in wbroot.find("m:sheets", NS)]

    relsroot = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    relmap = {r.get("Id"): r.get("Target") for r in relsroot}

    print("Sheets:", sheets)
    for name, rid in sheets:
        target = relmap[rid]
        if not target.startswith("xl/"):
            target = "xl/" + target
        sroot = ET.fromstring(z.read(target))
        rows = {}
        for c in sroot.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c"):
            ref = c.get("r")
            if ref is None:
                continue
            col, row = col_to_idx(ref)
            t = c.get("t")
            v = c.find("m:v", NS)
            val = None
            if v is not None:
                if t == "s":
                    val = shared[int(v.text)]
                else:
                    val = v.text
            else:
                isel = c.find("m:is", NS)
                if isel is not None:
                    val = "".join(tt.text or "" for tt in isel.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            rows.setdefault(row, {})[col] = val
        print(f"\n=== Sheet: {name} ===")
        for r in sorted(rows):
            cells = rows[r]
            line = " | ".join(f"{cells[c]}" for c in sorted(cells))
            print(f"row {r}: {line}")

